const raw = $json.message?.content;
if (typeof raw !== 'string') throw new Error('Ollama response is missing message.content');
let parsed;
try { parsed = JSON.parse(raw); } catch { throw new Error('Ollama did not return valid JSON for script'); }
if (typeof parsed.script !== 'string' || !parsed.script.trim()) throw new Error('Ollama script field is empty');
return { json: { script: parsed.script.trim() } };

const raw = $json.message?.content;
if (typeof raw !== 'string') throw new Error('Ollama response is missing message.content');
let parsed;
try { parsed = JSON.parse(raw); } catch { throw new Error('Ollama did not return valid JSON for scenes'); }
if (!Array.isArray(parsed.scenes) || parsed.scenes.length < 1 || parsed.scenes.length > 12) throw new Error('Expected 1 to 12 scenes');
const scenes = parsed.scenes.map((s, i) => {
  if (!s || typeof s.title !== 'string' || typeof s.narration !== 'string' || typeof s.imagePrompt !== 'string') throw new Error('Scene ' + (i + 1) + ' is missing title, narration, or imagePrompt');
  return { title: s.title, narration: s.narration, imagePrompt: s.imagePrompt };
});
return { json: { scenes } };

const body = $('Autovid Webhook').first().json.body || {};
const scene = body.scene || {};
const esc = (v) => String(v || '').replace(/[&<>\"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&apos;'}[c]));
const title = esc(scene.title || 'Autovid');
const prompt = esc(scene.imagePrompt || body.style || 'Cinematic visual');
const narration = esc(scene.narration || '');
const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="1080" height="1920" viewBox="0 0 1080 1920"><defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#101827"/><stop offset="0.55" stop-color="#243b55"/><stop offset="1" stop-color="#141e30"/></linearGradient><radialGradient id="r"><stop offset="0" stop-color="#38bdf8" stop-opacity=".55"/><stop offset="1" stop-color="#38bdf8" stop-opacity="0"/></radialGradient></defs><rect width="1080" height="1920" fill="url(#g)"/><circle cx="820" cy="460" r="560" fill="url(#r)"/><circle cx="120" cy="1450" r="460" fill="url(#r)" opacity=".65"/><path d="M0 1180 Q540 900 1080 1180 V1920 H0Z" fill="#07111f" opacity=".45"/><rect x="72" y="120" width="936" height="1680" rx="44" fill="none" stroke="#ffffff" stroke-opacity=".22" stroke-width="3"/><text x="110" y="260" fill="#7dd3fc" font-family="Arial,sans-serif" font-size="34" letter-spacing="8">AUTOVID • LOCAL AI</text><text x="110" y="820" fill="#ffffff" font-family="Arial,sans-serif" font-size="76" font-weight="700">${title}</text><foreignObject x="110" y="900" width="860" height="360"><div xmlns="http://www.w3.org/1999/xhtml" style="color:#dbeafe;font:32px Arial,sans-serif;line-height:1.4">${prompt}</div></foreignObject><foreignObject x="110" y="1450" width="860" height="250"><div xmlns="http://www.w3.org/1999/xhtml" style="color:#ffffff;font:28px Arial,sans-serif;line-height:1.5;opacity:.82">${narration.slice(0,260)}</div></foreignObject></svg>`;
const imageUrl = 'data:image/svg+xml;base64,' + Buffer.from(svg, 'utf8').toString('base64');
return { json: { imageUrl } };

const binary = $input.item.binary?.data;
if (!binary?.data) throw new Error('Piper did not return a WAV binary file in property data');
return { json: { audioUrl: 'data:audio/wav;base64,' + binary.data } };
